use std::{fs::{self,File},io::{self,Read},ffi::CString,os::{fd::{AsRawFd,FromRawFd},raw::{c_char,c_int},unix::fs::symlink},sync::{Arc,atomic::{AtomicBool,Ordering}}};
extern "C"{fn openat(dirfd:c_int,pathname:*const c_char,flags:c_int,...)->c_int;fn mkfifo(path:*const c_char,mode:u32)->c_int;}
const O_CLOEXEC:i32=0x80000;const O_NOFOLLOW:i32=0x20000;const O_NONBLOCK:i32=0x800;const O_PATH:i32=0x200000;
fn open_path(root:&File,path:&[u8])->Result<File,u16>{
 if path.ends_with(b"/") {return Err(403)}
 let parts:Vec<&[u8]>=path.split(|&c|c==b'/').filter(|s|!s.is_empty()&&*s!=b".").collect();if parts.is_empty(){return Err(403)}
 let mut cur:Option<File>=None;for (i,part) in parts.iter().enumerate(){let c=CString::new(*part).map_err(|_|400u16)?;let fd=unsafe{openat(cur.as_ref().unwrap_or(root).as_raw_fd(),c.as_ptr(),O_CLOEXEC|O_NOFOLLOW|if i+1==parts.len(){O_NONBLOCK}else{O_PATH})};if fd<0{let e=io::Error::last_os_error().raw_os_error().unwrap_or(0);return Err(if e==2{404}else{403})}let f=unsafe{File::from_raw_fd(fd)};let m=f.metadata().map_err(|_|403u16)?;if i+1==parts.len(){if !m.is_file(){return Err(403)}return Ok(f)}else{if m.file_type().is_symlink()||!m.is_dir(){return Err(403)}cur=Some(f)}} Err(404)
}
#[test]fn symlinks_fifo_and_rename_race(){let base=std::env::temp_dir().join(format!("openat-test-{}",std::process::id()));let _=fs::remove_dir_all(&base);fs::create_dir_all(base.join("root/d")).unwrap();fs::write(base.join("root/d/file"),b"inside").unwrap();fs::write(base.join("secret"),b"outside").unwrap();symlink(base.join("secret"),base.join("root/link")).unwrap();symlink(base.join("root/d"),base.join("root/dirlink")).unwrap();let p=CString::new(base.join("root/fifo").as_os_str().as_encoded_bytes()).unwrap();assert_eq!(unsafe{mkfifo(p.as_ptr(),0o600)},0);
 let root=File::open(base.join("root")).unwrap();let mut s=String::new();open_path(&root,b"/d/file").unwrap().read_to_string(&mut s).unwrap();assert_eq!(s,"inside");for p in [b"/link".as_slice(),b"/dirlink/file",b"/fifo",b"/d",b"/d/file/"]{assert_eq!(open_path(&root,p).err(),Some(403));}assert_eq!(open_path(&root,b"/missing").err(),Some(404));
 let target=base.join("root/race");fs::write(&target,b"inside").unwrap();let running=Arc::new(AtomicBool::new(true));let r=running.clone();let dir=base.join("root");let secret=base.join("secret");let writer=std::thread::spawn(move||{while r.load(Ordering::Relaxed){let tmp=dir.join("tmp");let _=fs::remove_file(&tmp);symlink(&secret,&tmp).unwrap();fs::rename(&tmp,dir.join("race")).unwrap();fs::write(&tmp,b"inside").unwrap();fs::rename(&tmp,dir.join("race")).unwrap();}});
 let before=fs::read_dir("/proc/self/fd").unwrap().count();for _ in 0..10000{match open_path(&root,b"/race"){Ok(mut f)=>{let mut v=Vec::new();f.read_to_end(&mut v).unwrap();assert_eq!(v,b"inside");},Err(e)=>assert!(e==403||e==404)}}running.store(false,Ordering::Relaxed);writer.join().unwrap();let after=fs::read_dir("/proc/self/fd").unwrap().count();assert_eq!(before,after);fs::remove_dir_all(base).unwrap();}
